public class CooperateDefectStyleFigureProvider extends DefaultFigureProvider {

	private static IFigureProvider singleton;

	public IFigure getFigure(Object object) {

		IFigure figure = null;
		Color color = null;
		Player rootActGroup = (Player) object;
		Player playerRule = rootActGroup;

		if (playerRule.isCooperate()) {
			//--ids  [playerRule, identityCooperate]

			color = ColorConstants.blue;

			//--ids  [playerRule, identityCooperate, playerRuleColorBlue]
			figure = Shapes.createOval();
			//--ids  [playerRule, identityCooperate, playerRuleColorBlue, playerRuleShapeOval]

			((Shape) figure).setFill(true);
			figure.setBackgroundColor(color);

		}
		if (!(playerRule.isCooperate())) {
			//--ids  [playerRule, identityCooperate, defector]

			color = ColorConstants.red;

			//--ids  [playerRule, identityCooperate, defector, playerRuleColorRed]
			figure = Shapes.createOval();
			//--ids  [playerRule, identityCooperate, defector, playerRuleColorRed, playerRuleShapeOval]

			((Shape) figure).setFill(true);
			figure.setBackgroundColor(color);

		}

		return figure;
	}

	public static IFigureProvider getDefault() {
		if (singleton == null) {
			singleton = new CooperateDefectStyleFigureProvider();
		}
		return singleton;
	}
}
